@SpringBootTest @AutoConfigureMockMvc
@AuditCleanupFixture
class Phase6IntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;
 @org.springframework.boot.test.mock.mockito.MockBean Clock clock;
 String nv,tk,username,password,pitch,marker;MockHttpSession admin;LocalDate day;List<Map<String,Object>> originalPermissions;
 JsonNode data(MvcResult r)throws Exception{return json.readTree(r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).path("data");}
 MockHttpSession login(String user,String pw)throws Exception{var r=mvc.perform(get("/api/auth/csrf")).andReturn();var s=(MockHttpSession)r.getRequest().getSession();var c=data(r);mvc.perform(post("/api/auth/login").session(s).header(c.path("headerName").asText(),c.path("token").asText()).param("identifier",user).param("password",pw)).andExpect(status().isOk());return s;}
 MockHttpSession login(String user)throws Exception{return login(user,System.getenv().getOrDefault("AUTH_TEST_PASSWORD","123456"));}
 ResultActions write(MockHttpSession s,String method,String path,Object body)throws Exception{var c=data(mvc.perform(get("/api/auth/csrf").session(s)).andReturn());return mvc.perform(request(org.springframework.http.HttpMethod.valueOf(method),path).session(s).header(c.path("headerName").asText(),c.path("token").asText()).contentType("application/json").content(json.writeValueAsString(body)));}
 Map<String,Object> employee(boolean active){return Map.of("hoTen",marker,"boPhan","Nhân viên sân bóng","trangThai",active,"ngayVaoLam",LocalDate.now().toString());}
 @BeforeEach void setup()throws Exception{org.mockito.Mockito.when(clock.instant()).thenReturn(Instant.now());org.mockito.Mockito.when(clock.getZone()).thenReturn(ZoneId.of("Asia/Ho_Chi_Minh"));org.mockito.Mockito.when(clock.withZone(org.mockito.ArgumentMatchers.any(ZoneId.class))).thenAnswer(i->Clock.fixed(clock.instant(),i.getArgument(0)));marker="Phase6 fixture "+UUID.randomUUID();pitch="P6"+UUID.randomUUID().toString().replace("-","").substring(0,8);username="p6_"+UUID.randomUUID().toString().substring(0,8);password=UUID.randomUUID().toString();day=LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")).plusDays(20);admin=login("admin");
 nv=data(write(admin,"POST","/api/admin/employees",employee(true)).andExpect(status().isOk()).andReturn()).path("MaNV").asText();
 tk=data(write(admin,"POST","/api/admin/accounts",Map.of("maNV",nv,"tenDangNhap",username,"matKhau",password,"maVaiTro","VT02")).andExpect(status().isOk()).andReturn()).path("MaTK").asText();
 jdbc.update("INSERT San(MaSan,TenSan,MaLoaiSan,TrangThai,MoTa) VALUES(?,?,?,?,?)",pitch,"Phase6 test sân","LS01","Trống",marker);
 }
 @AfterEach void cleanup(){
 if(originalPermissions!=null){jdbc.execute("DELETE PhanQuyen WHERE MaVaiTro='VT02'");for(var p:originalPermissions)jdbc.update("INSERT PhanQuyen(MaVaiTro,MaChucNang,Xem,Them,Sua,Xoa) VALUES('VT02',?,?,?,?,?)",p.get("MaChucNang"),p.get("Xem"),p.get("Them"),p.get("Sua"),p.get("Xoa"));originalPermissions=null;}
 if(pitch!=null){var ids=jdbc.queryForList("SELECT MaDatSan FROM DatSan WHERE MaSan=? AND GhiChu=?",String.class,pitch,marker);for(String id:ids){jdbc.update("DELETE h FROM HoanTien h JOIN ThanhToan t ON t.MaTT=h.MaTT WHERE t.MaDatSan=?",id);jdbc.update("DELETE ThanhToan WHERE MaDatSan=?",id);jdbc.update("DELETE HuyDatSan WHERE MaDatSan=?",id);jdbc.update("DELETE ChiTietDichVu WHERE MaDatSan=?",id);jdbc.update("DELETE HoaDon WHERE MaDatSan=?",id);jdbc.update("DELETE XacNhanSan WHERE MaDatSan=?",id);jdbc.update("DELETE NhatKyHeThong WHERE DoiTuong=?",id);jdbc.update("DELETE DatSan WHERE MaDatSan=?",id);}jdbc.update("DELETE San WHERE MaSan=? AND MoTa=?",pitch,marker);}
 if(tk!=null){jdbc.update("DELETE NhatKyHeThong WHERE MaTK=? OR DoiTuong=?",tk,tk);jdbc.update("DELETE TaiKhoan WHERE MaTK=? AND TenDangNhap=?",tk,username);}
 if(nv!=null){jdbc.update("DELETE NhatKyHeThong WHERE DoiTuong=? AND ChucNang=N'Quản trị'",nv);jdbc.update("DELETE NhanVien WHERE MaNV=? AND HoTen=?",nv,marker);}
 }
 @Test void employeeListDetailSearchEditAndStatus()throws Exception{mvc.perform(get("/api/admin/employees").param("q",nv).session(admin)).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(1));mvc.perform(get("/api/admin/employees/"+nv).session(admin)).andExpect(status().isOk());var b=new HashMap<String,Object>(employee(true));b.put("chucVu","Ca sáng");write(admin,"PUT","/api/admin/employees/"+nv,b).andExpect(status().isOk());assertEquals("Ca sáng",jdbc.queryForObject("SELECT ChucVu FROM NhanVien WHERE MaNV=?",String.class,nv));mvc.perform(get("/api/admin/employees").param("q",nv).param("active","false").session(admin)).andExpect(jsonPath("$.data.total").value(0));}
 @Test void lockedAccountCannotLoginAndActiveSessionExpires()throws Exception{var s=login(username,password);write(admin,"PUT","/api/admin/accounts/"+tk,Map.of("hoatDong",false,"maVaiTro","VT02")).andExpect(status().isOk());mvc.perform(get("/api/auth/me").session(s)).andExpect(status().isUnauthorized());var raw=mvc.perform(get("/api/auth/csrf")).andReturn();var c=data(raw);mvc.perform(post("/api/auth/login").session((MockHttpSession)raw.getRequest().getSession()).header(c.path("headerName").asText(),c.path("token").asText()).param("identifier",username).param("password",password)).andExpect(status().isUnauthorized());}
 @Test void unlockAndRoleChangeReloadExistingSession()throws Exception{var s=login(username,password);write(admin,"PUT","/api/admin/accounts/"+tk,Map.of("hoatDong",true,"maVaiTro","VT03")).andExpect(status().isOk());mvc.perform(get("/api/auth/me").session(s)).andExpect(jsonPath("$.data.maVaiTro").value("VT03"));mvc.perform(get("/api/reports/finance").param("from",day.toString()).param("to",day.toString()).session(s)).andExpect(status().isOk());write(admin,"PUT","/api/admin/accounts/"+tk,Map.of("hoatDong",false,"maVaiTro","VT03")).andExpect(status().isOk());write(admin,"PUT","/api/admin/accounts/"+tk,Map.of("hoatDong",true,"maVaiTro","VT03")).andExpect(status().isOk());login(username,password);}
 @Test void employeeStopLocksAccountAndCannotReopenUntilActive()throws Exception{var s=login(username,password);write(admin,"PUT","/api/admin/employees/"+nv,employee(false)).andExpect(status().isOk());mvc.perform(get("/api/auth/me").session(s)).andExpect(status().isUnauthorized());write(admin,"PUT","/api/admin/accounts/"+tk,Map.of("hoatDong",true,"maVaiTro","VT02")).andExpect(status().isConflict());assertEquals("Khóa",jdbc.queryForObject("SELECT TrangThai FROM TaiKhoan WHERE MaTK=?",String.class,tk));}
 @Test void resetIsHashedDoesNotLeakAndInvalidatesOldSession()throws Exception{var s=login(username,password);String next=UUID.randomUUID().toString();write(admin,"POST","/api/admin/accounts/"+tk+"/reset-password",Map.of("matKhau",next)).andExpect(status().isOk());mvc.perform(get("/api/auth/me").session(s)).andExpect(status().isUnauthorized());String hash=jdbc.queryForObject("SELECT MatKhau FROM TaiKhoan WHERE MaTK=?",String.class,tk);assertTrue(hash.startsWith("$2"));assertNotEquals(next,hash);login(username,next);String body=mvc.perform(get("/api/security/accounts").session(admin)).andReturn().getResponse().getContentAsString();assertFalse(body.contains(hash));assertFalse(body.contains(next));var logs=jdbc.queryForList("SELECT NoiDungThayDoi FROM NhatKyHeThong WHERE DoiTuong=?",String.class,tk);assertTrue(logs.stream().noneMatch(x->x.contains(next)||x.contains(password)||x.contains(hash)));}
 @Test void duplicateEmployeeAccountRejected()throws Exception{write(admin,"POST","/api/admin/accounts",Map.of("maNV",nv,"tenDangNhap",username+"x","matKhau",password,"maVaiTro","VT02")).andExpect(status().isConflict());}
 @Test void selfAdminLockDowngradeAndEmployeeStopBlocked()throws Exception{write(admin,"PUT","/api/admin/accounts/TK01",Map.of("hoatDong",false,"maVaiTro","VT04")).andExpect(status().isConflict());write(admin,"PUT","/api/admin/accounts/TK01",Map.of("hoatDong",true,"maVaiTro","VT02")).andExpect(status().isConflict());write(admin,"PUT","/api/admin/employees/NV01",employee(false)).andExpect(status().isConflict());}
 @Test void cannotChangeCustomerOwnershipOrCreateWeakPassword()throws Exception{write(admin,"PUT","/api/admin/accounts/"+tk,Map.of("hoatDong",true,"maVaiTro","VT01")).andExpect(status().isBadRequest());write(admin,"POST","/api/admin/accounts/"+tk+"/reset-password",Map.of("matKhau","123")).andExpect(status().isBadRequest());write(admin,"POST","/api/admin/accounts/"+tk+"/reset-password",Map.of("matKhau","ắ".repeat(30))).andExpect(status().isBadRequest());}
 @Test void adminOnlyWritesAndCustomerNoReport()throws Exception{var customer=login("khachhang");var staff=login(username,password);for(var s:List.of(customer,staff,login("ketoan"))){write(s,"POST","/api/admin/employees",employee(true)).andExpect(status().isForbidden());mvc.perform(get("/api/admin/logs").param("from",day.toString()).param("to",day.toString()).session(s)).andExpect(status().isForbidden());}mvc.perform(get("/api/reports/finance").param("from",day.toString()).param("to",day.toString()).session(customer)).andExpect(status().isForbidden());mvc.perform(get("/api/reports/finance").param("from",day.toString()).param("to",day.toString()).session(staff)).andExpect(status().isForbidden());}
 @Test void permissionGrantAndRevokeImmediateForStaffReports()throws Exception{originalPermissions=jdbc.queryForList("SELECT * FROM PhanQuyen WHERE MaVaiTro='VT02'");jdbc.update("UPDATE PhanQuyen SET Xem=0 WHERE MaVaiTro='VT02' AND MaChucNang='CN06'");var s=login(username,password);String url="/api/reports/usage";mvc.perform(get(url).param("from",day.toString()).param("to",day.toString()).session(s)).andExpect(status().isForbidden());var matrix=data(mvc.perform(get("/api/security/permissions").param("role","VT02").session(admin)).andReturn());var body=json.createArrayNode();for(var row:matrix.path("permissions")){var r=body.addObject();r.put("maChucNang",row.path("MaChucNang").asText());for(String k:List.of("Xem","Them","Sua","Xoa"))r.put(k.toLowerCase(),row.path(k).asBoolean());if("CN06".equals(r.path("maChucNang").asText()))r.put("xem",true);}write(admin,"PUT","/api/security/permissions/VT02",body).andExpect(status().isOk());mvc.perform(get(url).param("from",day.toString()).param("to",day.toString()).session(s)).andExpect(status().isOk());for(var r:body)if("CN06".equals(r.path("maChucNang").asText()))((com.fasterxml.jackson.databind.node.ObjectNode)r).put("xem",false);write(admin,"PUT","/api/security/permissions/VT02",body).andExpect(status().isOk());mvc.perform(get(url).param("from",day.toString()).param("to",day.toString()).session(s)).andExpect(status().isForbidden());}
 String create(String start,String end,boolean service)throws Exception{var b=new HashMap<String,Object>(Map.of("maSan",pitch,"maKH","KH01","ngayChoi",day.toString(),"gioBatDau",start,"gioKetThuc",end,"ghiChu",marker));if(service)b.put("dichVu",List.of(Map.of("maDV","SV03","soLuong",1,"quyCach","LOC_6")));return data(write(admin,"POST","/api/bookings",b).andExpect(status().isOk()).andReturn()).path("maDatSan").asText();}
 void pay(String id,int n,String method)throws Exception{
  // Create the receipt at the desired business time; never rewrite a successful receipt.
  org.mockito.Mockito.when(clock.instant()).thenReturn(day.atTime(8,0).atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toInstant());
  try{write(admin,"POST","/api/finance/bookings/"+id+"/payments",Map.of("soTien",n,"phuongThuc",method,"idempotencyKey",UUID.randomUUID().toString(),"daNhanTien",true)).andExpect(status().isOk());}
  finally{org.mockito.Mockito.when(clock.instant()).thenReturn(Instant.now());}
 }
 void reportingFixture()throws Exception{String a=create("13:00","15:00",true);pay(a,200000,"Tiền mặt");jdbc.update("INSERT XacNhanSan(MaXacNhan,MaDatSan,MaNV,ThoiGianNhan,ThoiGianKetThuc) VALUES(?,?,?,?,?)",pitch,a,nv,day.atTime(13,0),day.atTime(15,0));jdbc.update("UPDATE DatSan SET TrangThai=N'Đã sử dụng' WHERE MaDatSan=?",a);write(admin,"POST","/api/finance/bookings/"+a+"/invoice",Map.of()).andExpect(status().isOk());String b=create("16:00","17:00",false);pay(b,100000,"Chuyển khoản");write(admin,"POST","/api/bookings/"+b+"/cancel",Map.of("lyDo",marker)).andExpect(status().isOk());var detail=data(mvc.perform(get("/api/finance/bookings/"+b).session(admin)).andReturn());String ht=detail.path("refunds").get(0).path("maHT").asText();write(admin,"POST","/api/finance/refunds/"+ht+"/confirm",Map.of("phuongThuc","Chuyển khoản","lyDo",marker,"daHoanTien",true)).andExpect(status().isOk());jdbc.update("UPDATE HoanTien SET NgayHoan=?,NgayXacNhan=? WHERE MaHT=?",day.atTime(9,0),day.atTime(10,0),ht);}
 String params(){return "?from="+day+"&to="+day+"&pitch="+pitch;}
 @Test void usageMinutesCancelledAndOccupancyMatchSql()throws Exception{reportingFixture();var r=data(mvc.perform(get("/api/reports/usage"+params()).session(admin)).andExpect(status().isOk()).andReturn());assertEquals(2,r.path("totals").path("soBooking").asInt());assertEquals(1,r.path("totals").path("soDaSuDung").asInt());assertEquals(1,r.path("totals").path("soDaHuy").asInt());assertEquals(120,r.path("totals").path("phutDat").asInt());assertEquals(13.33,r.path("totals").path("tyLeLapDay").asDouble());assertEquals(jdbc.queryForObject("SELECT SUM(PhutDat) FROM V_Phase6_UsageBooking WHERE MaSan=? AND NgayChoi=?",Integer.class,pitch,day),r.path("totals").path("phutDat").asInt());}
 @Test void revenueVsCashRefundAndMethodsMatchSql()throws Exception{reportingFixture();var r=data(mvc.perform(get("/api/reports/finance"+params()).session(admin)).andExpect(status().isOk()).andReturn());var t=r.path("totals");assertEquals(260000,t.path("tienSan").asInt());assertEquals(58200,t.path("tienDichVu").asInt());assertEquals(318200,t.path("doanhThu").asInt());assertEquals(300000,t.path("tienThu").asInt());assertEquals(100000,t.path("tienHoan").asInt());assertEquals(200000,t.path("thucNhan").asInt());assertEquals(2,r.path("methods").size());assertEquals(0,jdbc.queryForObject("SELECT SUM(v.SoTienThucNhan) FROM V_ThuChiThucNhan v JOIN DatSan d ON d.MaDatSan=v.MaDatSan WHERE d.MaSan=?",BigDecimal.class,pitch).compareTo(BigDecimal.valueOf(t.path("thucNhan").asLong())));}
 @Test void dateRangeIsInclusiveAndFutureOtherDayExcluded()throws Exception{reportingFixture();mvc.perform(get("/api/reports/finance").param("from",day.plusDays(1).toString()).param("to",day.plusDays(1).toString()).param("pitch",pitch).session(admin)).andExpect(jsonPath("$.data.totals.thucNhan").value(0));mvc.perform(get("/api/reports/finance").param("from",day.minusDays(1).toString()).param("to",day.toString()).param("pitch",pitch).session(admin)).andExpect(jsonPath("$.data.totals.thucNhan").value(200000));}
 @Test void refundFiltersPaginationAndActor()throws Exception{reportingFixture();mvc.perform(get("/api/reports/refunds").param("from",day.toString()).param("to",day.toString()).param("status","Đã hoàn").param("method","Chuyển khoản").session(admin)).andExpect(status().isOk()).andExpect(jsonPath("$.data.rows[0].nguoiXuLy").exists());mvc.perform(get("/api/reports/refunds").param("from",day.toString()).param("to",day.toString()).param("status","Chờ duyệt").session(admin)).andExpect(jsonPath("$.data.total").value(0));}
 @Test void logsFiltersAreReadOnlyAndAudited()throws Exception{String today=LocalDate.now().toString();mvc.perform(get("/api/admin/logs").param("from",today).param("to",today).param("target",nv).param("module","Quản trị").session(admin)).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(1));write(admin,"DELETE","/api/admin/logs",Map.of()).andExpect(status().isMethodNotAllowed());}
 @Test void dashboardMatchesSqlAndDoesNotRepriceSnapshots()throws Exception{reportingFixture();var r=data(mvc.perform(get("/api/reports/dashboard").session(admin)).andExpect(status().isOk()).andReturn());String today=r.path("today").asText();assertEquals(jdbc.queryForObject("SELECT COUNT(*) FROM DatSan WHERE NgayChoi=?",Integer.class,today),r.path("usage").path("totals").path("soBooking").asInt());assertEquals(0,jdbc.queryForObject("SELECT ISNULL(SUM(SoTienThucNhan),0) FROM V_ThuChiThucNhan WHERE ThoiDiem>=? AND ThoiDiem<?",BigDecimal.class,today,LocalDate.parse(today).plusDays(1)).compareTo(BigDecimal.valueOf(r.path("finance").path("totals").path("thucNhan").asLong())));}
 @Test void invalidDatesPaginationAndFiltersRejected()throws Exception{mvc.perform(get("/api/reports/usage").param("from",day.toString()).param("to",day.minusDays(1).toString()).session(admin)).andExpect(status().isBadRequest());mvc.perform(get("/api/reports/finance").param("from","2000-01-01").param("to","2026-01-01").session(admin)).andExpect(status().isBadRequest());mvc.perform(get("/api/admin/employees").param("size","101").session(admin)).andExpect(status().isBadRequest());mvc.perform(get("/api/reports/refunds").param("from",day.toString()).param("to",day.toString()).param("method","fake").session(admin)).andExpect(status().isBadRequest());}
 @Test void unreturnedPrepaidBookingIsNotRevenue()throws Exception{String id=create("13:00","15:00",false);pay(id,260000,"Tiền mặt");mvc.perform(get("/api/reports/finance"+params()).session(admin)).andExpect(status().isOk()).andExpect(jsonPath("$.data.totals.doanhThu").value(0)).andExpect(jsonPath("$.data.totals.thucNhan").value(260000));}
 @Test void pendingRefundDoesNotReduceActualReceipts()throws Exception{String id=create("16:00","17:00",false);pay(id,100000,"Chuyển khoản");write(admin,"POST","/api/bookings/"+id+"/cancel",Map.of("lyDo",marker)).andExpect(status().isOk());mvc.perform(get("/api/reports/finance"+params()).session(admin)).andExpect(jsonPath("$.data.totals.tienHoan").value(0)).andExpect(jsonPath("$.data.totals.thucNhan").value(100000));}
 @Test void invalidEmployeeWriteDoesNotChangeStoredRecord()throws Exception{var body=new HashMap<String,Object>(employee(true));body.put("boPhan","Không hợp lệ");write(admin,"PUT","/api/admin/employees/"+nv,body).andExpect(status().isBadRequest());assertEquals("Nhân viên sân bóng",jdbc.queryForObject("SELECT BoPhan FROM NhanVien WHERE MaNV=?",String.class,nv));}
}
